def style(ws, widths):
    ws.freeze_panes = 'A2'
    ws.auto_filter.ref = ws.dimensions
    for c in ws[1]:
        c.fill = fill; c.font = font; c.alignment = center; c.border = Border(left=side,right=side,top=side,bottom=side)
    ws.row_dimensions[1].height = 28
    for row in ws.iter_rows(min_row=2):
        for c in row:
            c.alignment = wrap; c.border = Border(left=side,right=side,top=side,bottom=side)
    for idx,w in widths.items(): ws.column_dimensions[get_column_letter(idx)].width = w
